/* ---------------- FLOATERS ---------------- */
function buildFloaters(){
  const wrap = document.getElementById('floaters');
  const spots = [
    {top:'8%', left:'6%', w:130, rot:-10, delay:'0s', img:0},
    {top:'55%', left:'2%', w:100, rot:14, delay:'2s', img:1},
    {top:'12%', left:'82%', w:120, rot:12, delay:'1s', img:1},
    {top:'62%', left:'86%', w:150, rot:-8, delay:'3s', img:0},
    {top:'80%', left:'40%', w:90,  rot:6,  delay:'1.5s', img:1},
  ];
  spots.forEach(s=>{
    const img = document.createElement('img');
    img.src = FLOAT_IMAGES[s.img];
    img.style.top = s.top; img.style.left = s.left; img.style.width = s.w+'px';
    img.style.setProperty('--rot', s.rot+'deg');
    img.style.animationDelay = s.delay;
    wrap.appendChild(img);
  });
}



/* ---------------- MODALES COMPARTIDOS (carrito, login, registro) ---------------- */
const overlayBackdrop = document.getElementById('overlayBackdrop');
const allModals = ['cartModal','loginModal','regModal','sizeModal'].map(id=>document.getElementById(id));

function closeAllModals(){
  allModals.forEach(m=>m.classList.remove('open'));
  overlayBackdrop.classList.remove('open');
}
function openModal(id){
  closeAllModals();
  document.getElementById(id).classList.add('open');
  overlayBackdrop.classList.add('open');
}
overlayBackdrop.addEventListener('click', closeAllModals);

