/* ---------------- INIT ---------------- */
async function init(){
  buildFloaters();
  COLORS.forEach(c => { c.norm = c.img; });          // respaldo si algo falla
  await Promise.all(COLORS.map(async c=>{
    try{
      c.norm = await normalizeShirt(c.img);
      if(c.imgBack) c.normBack = await normalizeShirt(c.imgBack);
    }catch(err){ console.warn('No se pudo normalizar', c.id, err); }
  }));
  refreshAll();
  renderCart();
  buildGallery();
}
init();


/* ==========================================================================
   JEB — MEJORAS (todo lo de abajo es NUEVO; nada de lo anterior fue modificado)
   1) Estampado realista (mezcla multiply + mapa de desplazamiento)
   2) Limpieza de recuadros / selección
   3) Vista dinámica de espalda
   4) Visor 3D 360° con <model-viewer>
   Las funciones existentes (renderStage, select, positionEl) se "envuelven":
   se ejecuta tu código original y luego el nuevo.
   ========================================================================== */

/* ---------- Ajustes (puedes tocar estos valores) ---------- */
const JEB_FX = {
  inkOpacity:     0.93,   // opacidad de la tinta (deja pasar un poco de tela)
  shadeStrength:  1.4,    // cuánto se oscurecen pliegues/sombras sobre camisetas de color
  warpAmount:     2.2,    // deformación máx. (px a 340 px de ancho). 0 = sin deformación
  lightShirtLuma: 165,    // luminancia desde la cual la camiseta se considera "clara" (usa multiply CSS)
  texture3dWidth: 1024,   // ancho (px) de cada lado en la textura enviada al visor 3D
  modelSrc:       null    // ruta a tu propio .glb (ej. 'models/camiseta.glb'); null = modelo base incluido
};

/* Modelo 3D base neutro (camiseta-base.glb) embebido para que funcione sin servidor.
   UV: mitad izquierda de la textura = FRENTE, mitad derecha = ESPALDA. */
const TEE_GLB_B64 = '';

const _mapCache = new Map();   // mapas de la tela (sombras + desplazamiento) por color/lado/tamaño
const _baseCache = new Map();  // imágenes base decodificadas
const _inkImgs = new Map();    // imágenes subidas por el usuario, ya decodificadas
let _inkTok = 0, _inkRaf = 0, _inkSide = null, _lastSide = null, _fontsP = null;
const fontsOnce = () => _fontsP || (_fontsP = fontsReady());   // las tipografías se esperan una sola vez

/* ======================================================================
   3) VISTA DE ESPALDA
   No hay foto trasera en COLORS, así que se genera a partir del frente:
   se espeja, se tapa el escote delantero y se dibuja un cuello trasero.
   Si algún día agregas c.imgBack, ese tiene prioridad (init ya lo normaliza).
   ====================================================================== */
async function makeBackView(src){
  const im = await loadImg(src), W = im.naturalWidth, H = im.naturalHeight;
  const cv = document.createElement('canvas'); cv.width = W; cv.height = H;
  const x = cv.getContext('2d', { willReadFrequently:true });
  x.translate(W, 0); x.scale(-1, 1); x.drawImage(im, 0, 0); x.setTransform(1,0,0,1,0,0);
  const img = x.getImageData(0,0,W,H), d = img.data;
  let top = H, bot = -1, minX = W, maxX = -1;
  for(let yy=0; yy<H; yy++) for(let xx=0; xx<W; xx++){
    if(d[(yy*W+xx)*4+3] > 20){ if(yy<top)top=yy; if(yy>bot)bot=yy; if(xx<minX)minX=xx; if(xx>maxX)maxX=xx; }
  }
  if(bot < 0) return src;
  const bh = bot-top, bw = maxX-minX;
  let sx = 0, n = 0;                                   // centro del cuello (filas superiores)
  for(let yy=top; yy<top+bh*.04; yy++) for(let xx=minX; xx<=maxX; xx++) if(d[(yy*W+xx)*4+3] > 20){ sx += xx; n++; }
  const cx = n ? sx/n : W/2;
  let r=0, g=0, b=0, m=0;                              // color de la tela justo bajo el cuello
  for(let yy=Math.floor(top+bh*.22); yy<top+bh*.30; yy++) for(let xx=Math.floor(cx-bw*.12); xx<cx+bw*.12; xx++){
    const p = (yy*W+xx)*4; if(d[p+3] > 200){ r+=d[p]; g+=d[p+1]; b+=d[p+2]; m++; }
  }
  if(m){ r/=m; g/=m; b/=m; } else { r=g=b=128; }
  const ncy = top+bh*.075, rx = bw*.175, ry = bh*.085;  // parche que tapa el escote delantero
  for(let yy=Math.max(0,Math.floor(ncy-ry)); yy<=Math.min(H-1,Math.ceil(ncy+ry)); yy++){
    for(let xx=Math.max(0,Math.floor(cx-rx)); xx<=Math.min(W-1,Math.ceil(cx+rx)); xx++){
      const p = (yy*W+xx)*4; if(d[p+3] <= 20) continue;
      const dd = ((xx-cx)/rx)**2 + ((yy-ncy)/ry)**2; if(dd >= 1) continue;
      const mk = Math.min(1,(1-dd)/.25), sh = 1 - .10*Math.min(1, Math.max(0,(ncy-yy)/ry));
      d[p]   = d[p]  *(1-mk) + r*sh*mk;
      d[p+1] = d[p+1]*(1-mk) + g*sh*mk;
      d[p+2] = d[p+2]*(1-mk) + b*sh*mk;
    }
  }
  x.putImageData(img,0,0);
  x.save();                                            // cinta del cuello trasero (solo sobre la prenda)
  x.globalCompositeOperation = 'source-atop';
  x.strokeStyle = (r+g+b)/3 > 90 ? 'rgba(0,0,0,.27)' : 'rgba(255,255,255,.15)';
  x.lineWidth = Math.max(2, bw*.018); x.filter = 'blur(0.8px)';
  const by0 = top+bh*.005, by1 = top+bh*.087;
  x.beginPath(); x.ellipse(cx,(by0+by1)/2,bw*.165,(by1-by0)/2,0,8*Math.PI/180,172*Math.PI/180); x.stroke();
  x.restore();
  return cv.toDataURL('image/png');
}

/* Intercepta c.norm / c.normBack: cada vez que init() guarda la foto normalizada,
   se regenera la espalda. shirtSrc() ya usa c.normBack, así que no hay que tocarla. */
COLORS.forEach(c=>{
  let _norm = c.norm, _real = c.normBack;
  const genBack = ()=>{
    const tok = c._bt = (c._bt||0) + 1;
    makeBackView(_norm).then(url=>{
      if(c._bt !== tok) return;
      c._backGen = url; _mapCache.clear();
      if(c.id === selectedColorId && currentSide === 'back') renderStage();
      markDirty3D();
    }).catch(err=>console.warn('No se pudo generar la espalda', c.id, err));
  };
  Object.defineProperty(c,'norm',{ configurable:true, enumerable:true, get(){ return _norm; }, set(v){ _norm = v; genBack(); } });
  Object.defineProperty(c,'normBack',{ configurable:true, enumerable:true, get(){ return _real || c._backGen || _norm; }, set(v){ _real = v; } });
  if(_norm) genBack();
});

/* ======================================================================
   1) ESTAMPADO REALISTA
   La tinta se dibuja en un canvas 2D (#inkCanvas) encima de la camiseta:
   - Camisetas CLARAS: el canvas se mezcla con CSS mix-blend-mode:multiply,
     así las arrugas y la textura de la tela se transparentan.
   - Camisetas OSCURAS/de color: multiply puro haría invisible el diseño, así que
     se aplica el equivalente en Canvas: la luminancia de la tela (sombras y pliegues)
     multiplica el color de la tinta, conservando el color elegido.
   - En ambos casos un MAPA DE DESPLAZAMIENTO (derivado de los pliegues reales de la
     foto) deforma ligeramente bordes de texto/imagen.
   ====================================================================== */
function boxBlur(src, W, H, r){
  const tmp = new Float32Array(W*H), out = new Float32Array(W*H), k = 2*r+1;
  for(let y=0; y<H; y++){
    let s = 0, row = y*W;
    for(let x=-r; x<=r; x++) s += src[row + Math.min(W-1, Math.max(0,x))];
    for(let x=0; x<W; x++){
      tmp[row+x] = s/k;
      s += src[row + Math.min(W-1, x+r+1)] - src[row + Math.max(0, x-r)];
    }
  }
  for(let x=0; x<W; x++){
    let s = 0;
    for(let y=-r; y<=r; y++) s += tmp[Math.min(H-1, Math.max(0,y))*W + x];
    for(let y=0; y<H; y++){
      out[y*W+x] = s/k;
      s += tmp[Math.min(H-1, y+r+1)*W + x] - tmp[Math.max(0, y-r)*W + x];
    }
  }
  return out;
}

/* Mapas de la tela: factor de sombra (0-255) + desplazamiento X/Y (px*16) */
function buildFabricMaps(base, W, H){
  const cv = document.createElement('canvas'); cv.width = W; cv.height = H;
  const cx = cv.getContext('2d', { willReadFrequently:true }); cx.drawImage(base, 0, 0, W, H);
  const d = cx.getImageData(0,0,W,H).data, n = W*H;
  const L = new Float32Array(n), A = new Uint8Array(n);
  let sum = 0, cnt = 0;
  for(let i=0, p=0; i<n; i++, p+=4){
    A[i] = d[p+3]; L[i] = .299*d[p] + .587*d[p+1] + .114*d[p+2];
    const x = i % W, y = (i/W)|0;
    if(A[i] > 200 && x > W*.3 && x < W*.7 && y > H*.3 && y < H*.7){ sum += L[i]; cnt++; }
  }
  const ref = Math.max(20, cnt ? sum/cnt : 128), kk = W/340;
  const fine = boxBlur(L, W, H, 1), soft = boxBlur(L, W, H, Math.max(2, Math.round(2*kk)));
  const step = Math.max(1, Math.round(2*kk)), amp = JEB_FX.warpAmount * kk;
  const factor = new Uint8Array(n), dx = new Int8Array(n), dy = new Int8Array(n);
  for(let y=0; y<H; y++){
    for(let x=0; x<W; x++){
      const i = y*W + x;
      if(A[i] < 200){ factor[i] = 255; continue; }
      const f = 1 - (1 - fine[i]/ref) * JEB_FX.shadeStrength;
      factor[i] = Math.round(255 * Math.min(1, Math.max(.28, f)));
      if(amp > 0 && x >= step && x < W-step && y >= step && y < H-step){
        const gx = (soft[i+step] - soft[i-step]) / ref, gy = (soft[i+step*W] - soft[i-step*W]) / ref;
        dx[i] = Math.round(Math.max(-amp, Math.min(amp, gx*14*kk)) * 16);
        dy[i] = Math.round(Math.max(-amp, Math.min(amp, gy*14*kk)) * 16);
      }
    }
  }
  return { factor, dx, dy, light: ref > JEB_FX.lightShirtLuma };
}

function getBaseImg(c, side){
  const src = shirtSrc(c, side), key = c.id + '|' + side + '|' + src.length;
  if(!_baseCache.has(key)){
    if(_baseCache.size > 14) _baseCache.clear();
    _baseCache.set(key, loadImg(src).then(im => ({ im, key })));
  }
  return _baseCache.get(key);
}
function getMaps(baseObj, W, H){
  const key = baseObj.key + '|' + W;
  if(!_mapCache.has(key)){
    if(_mapCache.size > 10) _mapCache.clear();
    _mapCache.set(key, buildFabricMaps(baseObj.im, W, H));
  }
  return _mapCache.get(key);
}

/* Dibuja las capas planas (misma matemática que renderComposite) */
let _flat = null;
function paintFlat(list, W, H){
  if(!_flat) _flat = document.createElement('canvas');
  if(_flat.width !== W || _flat.height !== H){ _flat.width = W; _flat.height = H; }
  const x = _flat.getContext('2d', { willReadFrequently:true }), k = W / STAGE_BASE_W;
  x.clearRect(0,0,W,H);
  for(const l of list){
    x.save();
    x.translate(l.x*W, l.y*H);
    x.rotate((l.rot||0) * Math.PI / 180);
    if(l.type === 'text'){
      x.font = `600 ${22*k*l.scale}px ${l.font}`;
      x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillStyle = l.color;
      x.fillText(l.text, 0, 0);
    } else {
      let im = _inkImgs.get(l.src);
      if(!im){ im = new Image(); im.onload = ()=>{ scheduleInk(); }; im.src = l.src; _inkImgs.set(l.src, im); }
      if(im.complete && im.naturalWidth){
        const w = 90*k*l.scale, h = w * im.naturalHeight / im.naturalWidth;
        x.drawImage(im, -w/2, -h/2, w, h);
      }
    }
    x.restore();
  }
  return x.getImageData(0,0,W,H);
}

/* Desplazamiento (bilineal con alfa premultiplicado) + sombras de la tela */
function inkPixels(list, W, H, maps){
  const src = paintFlat(list, W, H), s = src.data, out = new ImageData(W, H), o = out.data;
  const shade = !maps.light, op = JEB_FX.inkOpacity;
  const { factor, dx, dy } = maps;
  for(let y=0; y<H; y++){
    for(let x=0; x<W; x++){
      const i = y*W + x;
      const sx = x + dx[i]/16, sy = y + dy[i]/16;
      const x0 = Math.floor(sx), y0 = Math.floor(sy);
      if(x0 < 0 || y0 < 0 || x0 >= W-1 || y0 >= H-1) continue;
      const p00 = (y0*W + x0) << 2, p10 = p00 + 4, p01 = p00 + (W<<2), p11 = p01 + 4;
      const a00 = s[p00+3], a10 = s[p10+3], a01 = s[p01+3], a11 = s[p11+3];
      if(!(a00 | a10 | a01 | a11)) continue;
      const fx = sx - x0, fy = sy - y0;
      const w00 = (1-fx)*(1-fy)*a00, w10 = fx*(1-fy)*a10, w01 = (1-fx)*fy*a01, w11 = fx*fy*a11;
      const aw = w00 + w10 + w01 + w11; if(aw <= 0) continue;
      let r = (s[p00]*w00 + s[p10]*w10 + s[p01]*w01 + s[p11]*w11) / aw;
      let g = (s[p00+1]*w00 + s[p10+1]*w10 + s[p01+1]*w01 + s[p11+1]*w11) / aw;
      let b = (s[p00+2]*w00 + s[p10+2]*w10 + s[p01+2]*w01 + s[p11+2]*w11) / aw;
      if(shade){ const f = factor[i] / 255; r *= f; g *= f; b *= f; }
      const q = i << 2;
      o[q] = r; o[q+1] = g; o[q+2] = b; o[q+3] = aw * op;
    }
  }
  return out;
}

async function drawInk(){
  const cv = $('inkCanvas'); if(!cv || !stage.clientWidth) return;
  const tok = ++_inkTok, c = getColor(), side = currentSide;
  const W = Math.max(200, Math.round(stage.clientWidth * Math.min(window.devicePixelRatio||1, 2)));
  const H = Math.round(W * 410 / 340);
  try{
    await fontsOnce();
    const base = await getBaseImg(c, side);
    if(tok !== _inkTok) return;
    const maps = getMaps(base, W, H);
    const data = inkPixels(layers.filter(l => l.side === side), W, H, maps);
    if(tok !== _inkTok) return;
    if(cv.width !== W || cv.height !== H){ cv.width = W; cv.height = H; }
    cv.getContext('2d').putImageData(data, 0, 0);
    cv.classList.toggle('multiply', maps.light);   // CSS mix-blend-mode: multiply en camisetas claras
    stage.classList.add('realistic');
    _inkSide = side;
  }catch(err){
    console.warn('Estampado realista no disponible, se usa el modo plano', err);
    stage.classList.remove('realistic');
  }
}
function scheduleInk(){
  if(_inkRaf) return;
  _inkRaf = requestAnimationFrame(()=>{ _inkRaf = 0; drawInk(); markDirty3D(); });
}

/* Se "envuelven" las funciones originales: primero corre tu código, luego el nuevo */
const _renderStage = renderStage;
renderStage = function(){
  const swapping = _lastSide !== null && _lastSide !== currentSide;
  _renderStage();
  if(swapping){
    const cv = $('inkCanvas'); if(cv) cv.getContext('2d').clearRect(0,0,cv.width,cv.height);
    stage.classList.add('swap'); setTimeout(()=>stage.classList.remove('swap'), 170);
  }
  _lastSide = currentSide;
  document.querySelectorAll('#viewTabs button').forEach(b => b.setAttribute('aria-selected', b.dataset.side === currentSide));
  scheduleInk();
};
const _positionEl = positionEl;
positionEl = function(el, l){ _positionEl(el, l); scheduleInk(); };

/* ======================================================================
   2) RECUADROS Y CONTROLES: vista limpia
   ====================================================================== */
function updateEditingState(){
  const has = layers.some(l => l.side === currentSide);
  stage.classList.toggle('editing', selectedLayerId !== null);
  stage.classList.toggle('clean', has && selectedLayerId === null);
}
const _select = select;
select = function(id){ _select(id); updateEditingState(); };

/* clic/toque fuera de la camiseta y del panel de edición = deseleccionar (activeLayerId = null) */
document.addEventListener('pointerdown', e=>{
  if(selectedLayerId === null) return;
  if(e.target.closest('#stage, .panel')) return;
  select(null);
}, true);
document.addEventListener('keydown', e=>{ if(e.key === 'Escape' && selectedLayerId !== null) select(null); });
$('hideControls').addEventListener('click', ()=>select(null));
updateEditingState();

/* ======================================================================
   4) VISOR 3D 360° (<model-viewer>)
   Toma los canvas 2D de frente y espalda, los une en un atlas y lo aplica
   como baseColorTexture PBR del modelo. Se actualiza solo (con debounce).
   ====================================================================== */
const TEE = { ready:false, visible:false, busy:false, dirty:true, timer:0 };
const view3dStatus = txt => { const s = $('view3dStatus'); if(s) s.textContent = txt || ''; };

async function buildAtlas(Wt){
  await fontsOnce();
  const c = getColor(), H = Math.round(Wt * 410 / 340);
  const at = document.createElement('canvas'); at.width = Wt*2; at.height = H;
  const x = at.getContext('2d');
  x.fillStyle = c.hex; x.fillRect(0,0,Wt*2,H);          // evita bordes negros en la silueta
  const sides = ['front','back'];
  for(let i=0; i<2; i++){
    const side = sides[i], base = await getBaseImg(c, side);
    const tmp = document.createElement('canvas'); tmp.width = Wt; tmp.height = H;
    const tx = tmp.getContext('2d');
    tx.drawImage(base.im, 0, 0, Wt, H);
    const list = layers.filter(l => l.side === side);
    if(list.length){
      const maps = getMaps(base, Wt, H);
      const ink = document.createElement('canvas'); ink.width = Wt; ink.height = H;
      ink.getContext('2d').putImageData(inkPixels(list, Wt, H, maps), 0, 0);
      tx.globalCompositeOperation = maps.light ? 'multiply' : 'source-over';
      tx.drawImage(ink, 0, 0);
      tx.globalCompositeOperation = 'source-over';
    }
    x.drawImage(tmp, i*Wt, 0);
  }
  return at;
}

async function update3D(force){
  const mv = $('tee3d');
  if(!mv || !TEE.ready || (!TEE.visible && !force)) return;
  if(TEE.busy){ TEE.dirty = true; return; }
  TEE.busy = true; TEE.dirty = false;
  view3dStatus('Aplicando tu diseño…');
  try{
    const atlas = await buildAtlas(JEB_FX.texture3dWidth);
    const blob = await new Promise(res => atlas.toBlob(res, 'image/png'));
    const url = URL.createObjectURL(blob);
    const tex = await mv.createTexture(url);                 // textura PBR desde el canvas
    const pbr = mv.model.materials[0].pbrMetallicRoughness;
    pbr.baseColorTexture.setTexture(tex);
    pbr.setBaseColorFactor([1,1,1,1]);
    pbr.setMetallicFactor(0);
    pbr.setRoughnessFactor(0.92);
    URL.revokeObjectURL(url);
    view3dStatus(layers.length ? 'Diseño aplicado. Gira, acerca y revisa por delante y por detrás.' : 'Camiseta sin estampado. Agrega texto o imagen en el personalizador.');
  }catch(err){
    console.warn('Visor 3D:', err);
    view3dStatus('No se pudo aplicar la textura 3D. Revisa tu conexión (el visor se carga desde el CDN de Google).');
  }finally{
    TEE.busy = false;
    if(TEE.dirty) markDirty3D();
  }
}
function markDirty3D(){
  TEE.dirty = true;
  if(!TEE.ready) return;
  clearTimeout(TEE.timer);
  TEE.timer = setTimeout(()=>update3D(false), 450);
}

function initViewer3D(){
  const mv = $('tee3d'); if(!mv) return;
  try{
    if(JEB_FX.modelSrc) mv.src = JEB_FX.modelSrc;
    else{
      const bin = atob(TEE_GLB_B64), u8 = new Uint8Array(bin.length);
      for(let i=0; i<bin.length; i++) u8[i] = bin.charCodeAt(i);
      mv.src = URL.createObjectURL(new Blob([u8], { type:'model/gltf-binary' }));
    }
  }catch(err){ console.warn('Modelo 3D', err); }
  mv.addEventListener('load', ()=>{ TEE.ready = true; update3D(true); });
  mv.addEventListener('error', ()=>view3dStatus('No se pudo cargar el modelo 3D.'));
  if('IntersectionObserver' in window){
    new IntersectionObserver(es=>{
      TEE.visible = es[0].isIntersecting;
      if(TEE.visible && TEE.dirty) update3D(false);
    }, { threshold:.15 }).observe($('visor3d'));
  } else TEE.visible = true;

  const orbit = th => { mv.autoRotate = false; mv.cameraOrbit = th + 'deg 80deg auto'; };
  $('view3dFront').addEventListener('click', ()=>orbit(0));
  $('view3dBack').addEventListener('click', ()=>orbit(180));
  $('view3dSpin').addEventListener('click', e=>{
    mv.autoRotate = !mv.autoRotate;
    e.currentTarget.setAttribute('aria-pressed', mv.autoRotate);
  });
  $('view3dRefresh').addEventListener('click', ()=>update3D(true));
  $('goView3d').addEventListener('click', ()=>{
    $('visor3d').scrollIntoView({ behavior:'smooth' });
    update3D(true);
  });
}
initViewer3D();